-- 58 Lamplit Mine: the slopes, the planks and the shadows are the tilemap's
-- (the tileset's `shapes`, `tilemap_occluder`); this carries the lamp,
-- breaks and mends rock, rolls the boulders and flickers the lanterns.
-- Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/58-lamplit-mine.scene"
local COLS, ROWS = 40, 22
local BOULDERS = { { -336.0, -48.0 }, { 144.0, 48.0 }, { 272.0, 48.0 } }
local captions = true
local mine, lamp, status
local lanterns, boulders = {}, {}
local broken, edits = {}, 0
local t = 0

function init(entity)
    mine = Entity.find_by_name("Mine")
    lamp = Entity.find_by_name("Lamp")
    status = Entity.find_by_name("Status")
    for i = 1, 3 do lanterns[i] = Entity.find_by_name("LanternLight" .. i) end
    for i = 1, #BOULDERS do boulders[i] = Entity.find_by_name("Boulder" .. i) end
end

local function solid_edge(tx, ty)
    -- The outer rock stays, so nothing can fall out of the world.
    return tx < 2 or ty < 1 or tx > COLS - 6 or ty > ROWS - 3
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    local mx, my = Input.get_mouse_world_position()
    if lamp and mx then Transform.set_position(lamp, mx, my) end
    if mine and mx and Input.is_mouse_left_just_pressed() then
        local tx, ty = Tilemap.world_to_tile(mine, mx, my)
        if tx and not solid_edge(tx, ty) then
            local key = tx .. "," .. ty
            local here = Tilemap.get_tile(mine, "rock", tx, ty)
            if here and here > 0 then
                broken[key] = here
                Tilemap.set_tile(mine, "rock", tx, ty, nil)
                edits = edits + 1
            elseif broken[key] then
                Tilemap.set_tile(mine, "rock", tx, ty, broken[key])
                broken[key] = nil
                edits = edits + 1
            end
        end
    end
    if Input.is_key_just_pressed("B") then
        for i, b in ipairs(boulders) do
            if b then
                Transform.set_position(b, BOULDERS[i][1], BOULDERS[i][2])
                Physics.set_velocity(b, 0, 0)
            end
        end
    end
    t = t + dt
    for i, l in ipairs(lanterns) do
        if l then
            Lighting.set_intensity(l, 2.3 + 0.18 * math.sin(t * 9 + i * 2.3) + 0.1 * math.sin(t * 23 + i))
        end
    end
    if status then UI.set_text(status, edits == 0 and "click the rock" or (edits .. " rocks broken or mended")) end
end
